#include <stdio.h>
int main(void){
    int a[]={1,2,3}, b[]={2,3,4}, n=3, m=3;
    printf("intersection: ");
    for (int i=0;i<n;i++) for (int j=0;j<m;j++) if (a[i]==b[j]) printf("%d ", a[i]);
    printf("\nunion: ");
    for (int i=0;i<n;i++) printf("%d ", a[i]);
    for (int j=0;j<m;j++){ int f=0; for(int i=0;i<n;i++) if(b[j]==a[i]) f=1; if(!f) printf("%d ", b[j]); }
    printf("\ndifference A\\B: ");
    for (int i=0;i<n;i++){ int f=0; for(int j=0;j<m;j++) if(a[i]==b[j]) f=1; if(!f) printf("%d ", a[i]); }
    printf("\n");
    return 0;
}
